def set_area_for_selected_clients(self):
        """Set one area for all selected clients in the Clients tab (current mode only)."""
        try:
            sel = list(self.clients_tree.selection())
        except Exception:
            sel = []
        if not sel:
            messagebox.showwarning('Select', 'Please select one or more clients first.')
            return

        area = (getattr(self, 'bulk_area_var', tk.StringVar(value='')).get() or '').strip()
        try:
            areas = set(self.db.get_all_areas() or [])
        except Exception:
            areas = set()

        if area and areas and (area not in areas):
            messagebox.showerror('Invalid', 'Selected area is not in your Areas list. Please add it first.')
            return

        updated = 0
        for iid in sel:
            try:
                name = self.clients_tree.item(iid, 'values')[0]
            except Exception:
                continue
            if not name:
                continue

            # Infer actual loan_type from the row (supports 7x7-only rows shown in Regular view)
            lt = self._mode_filter()
            try:
                tags = self.clients_tree.item(iid, 'tags') or ()
                for t in tags:
                    if str(t).startswith('lt:'):
                        lt = str(t).split(':', 1)[1]
                        break
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0458', 'suppressed exception excpass_0458', __spina_exc)
                pass

            try:
                self.db.update_client(name, area=area, loan_type=lt)
                updated += 1
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0459', 'suppressed exception excpass_0459', __spina_exc)
                pass

        self.refresh_clients()
        self.refresh_reports()
        self.refresh_data_grid()
        messagebox.showinfo('Done', f'Updated area for {updated} client(s).')

def _maybe_suggest_link_clients(self, name, loan_type=None):
    """Auto-suggest linking when a matching client exists in the other loan type.

    - YES links both rows (same person_uid).
    - NO sets link_opt_out=1 for BOTH rows so you won't be asked again from either side,
      unless you manually link later.
    """
    try:
        nm = (name or '').strip()
        if not nm:
            return

        lt = (loan_type or self._mode_filter() or 'Regular')
        if str(lt).lower().replace(' ', '') in ('7x7', '7×7'):
            lt = '7x7'
        else:
            lt = 'Regular'
        other_lt = '7x7' if lt == 'Regular' else 'Regular'

        cur_info = self.db.get_client_info(nm, loan_type=lt) or {}
        if not cur_info:
            return

        # If user opted out for this row, don't prompt
        try:
            if int(cur_info.get('link_opt_out') or 0) == 1:
                return
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0533', 'suppressed exception excpass_0533', __spina_exc)
            pass

        other_info = self.db.get_client_info(nm, loan_type=other_lt) or {}
        if not other_info:
            return

        # If already linked, skip
        pu1 = (cur_info.get('person_uid') or '').strip()
        pu2 = (other_info.get('person_uid') or '').strip()
        if pu1 and pu2 and pu1 == pu2:
            return

        msg = (
            f"'{nm}' also exists as {other_lt}.\n\n"
            "Do you want to LINK them so you can recognize they are the same person?\n"
            "(They remain separate records: Regular and 7x7.)\n\n"
            "Choose YES to link, NO to keep them separate."
        )

        uid_a = (cur_info.get('client_uid') or '').strip()
        uid_b = (other_info.get('client_uid') or '').strip()

        if messagebox.askyesno('Link Regular + 7x7?', msg):
            ok = False
            try:
                ok = self.db.link_client_uids(uid_a, uid_b, source='clients:auto_suggest')
            except Exception:
                ok = False
            if ok:
                try:
                    messagebox.showinfo('Linked', f"Linked '{nm}' (Regular + 7x7).") 
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0534', 'suppressed exception excpass_0534', __spina_exc)
                    pass
                try:
                    self.refresh_clients()
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0535', 'suppressed exception excpass_0535', __spina_exc)
                    pass
            return
        else:
            # Persist NO on BOTH rows so the prompt won't appear from the other loan type either
            try:
                if uid_a:
                    self.db.set_link_opt_out_by_uid(uid_a, 1, source='clients:auto_suggest:no')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0536', 'suppressed exception excpass_0536', __spina_exc)
                pass
            try:
                if uid_b:
                    self.db.set_link_opt_out_by_uid(uid_b, 1, source='clients:auto_suggest:no')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0537', 'suppressed exception excpass_0537', __spina_exc)
                pass
            return
    except Exception:
        return


    def link_selected_client(self):
        """Manually link the selected client to another loan type record."""
        sel = self.clients_tree.selection()
        if not sel:
            messagebox.showwarning('Select', 'Please select a client first.')
            return
        iid = sel[0]
        name = self.clients_tree.item(iid, 'values')[0]
        lt = self._mode_filter()
        try:
            tags = self.clients_tree.item(iid, 'tags') or ()
            for t in tags:
                if str(t).startswith('lt:'):
                    lt = str(t).split(':', 1)[1]
                    break
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0538', 'suppressed exception excpass_0538', __spina_exc)
            pass
        other_lt = '7x7' if lt == 'Regular' else 'Regular'

        cur_info = self.db.get_client_info(name, loan_type=lt) or {}
        if not cur_info:
            messagebox.showwarning('Missing', 'Selected client not found.')
            return

        # Do not allow opening the link dialog for a client that is already linked.
        if (cur_info.get('person_uid') or '').strip():
            messagebox.showinfo('Already Linked', f"'{name}' ({lt}) is already linked. Unlink it first.")
            return

        # Only show unlinked targets from the other loan type.
        other_names = []
        try:
            for _nm in (self.db.get_all_clients(loan_type=other_lt) or []):
                _info = self.db.get_client_info(_nm, loan_type=other_lt) or {}
                if not (_info.get('person_uid') or '').strip():
                    other_names.append(_nm)
        except Exception:
            other_names = []

        if not other_names:
            messagebox.showinfo('No records', f'No unlinked {other_lt} clients exist yet.')
            return

        win = tk.Toplevel(self.root)
        win.title('Link Client')
        win.transient(self.root)
        win.grab_set()

        frm = ttk.Frame(win, padding=12)
        frm.pack(fill='both', expand=True)

        ttk.Label(frm, text=f"Link '{name}' ({lt}) to:", font=('TkDefaultFont', 10, 'bold')).pack(anchor='w', pady=(0,6))
        ttk.Label(frm, text=f"Choose a {other_lt} client to link.\nRecords stay separate, this only marks them as the same person.").pack(anchor='w', pady=(0,10))

        var = tk.StringVar(value=name if name in other_names else '')
        cb = ttk.Combobox(frm, textvariable=var, values=other_names, width=35)
        cb.pack(anchor='w', pady=(0,10))
        try:
            cb.focus_set()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0539', 'suppressed exception excpass_0539', __spina_exc)
            pass

        btns = ttk.Frame(frm)
        btns.pack(fill='x')

        def do_link():
            target = (var.get() or '').strip()
            if not target:
                messagebox.showwarning('Select', 'Please choose a client to link.')
                return
            other_info = self.db.get_client_info(target, loan_type=other_lt) or {}
            if not other_info:
                messagebox.showwarning('Missing', 'Target client not found.')
                return
            uid_a = (cur_info.get('client_uid') or '').strip()
            uid_b = (other_info.get('client_uid') or '').strip()
            if not uid_a or not uid_b:
                messagebox.showerror('Error', 'Missing client UID. Try reopening the app to allow UID backfill.')
                return
            pu_a = (cur_info.get('person_uid') or '').strip()
            pu_b = (other_info.get('person_uid') or '').strip()
            if pu_a and pu_b and pu_a == pu_b:
                messagebox.showinfo('Already Linked', f"'{name}' and '{target}' are already linked.")
                return
            if pu_a or pu_b:
                who = name if pu_a else target
                messagebox.showinfo('Already Linked', f"'{who}' is already linked. Unlink it first.")
                return
            ok = self.db.link_client_uids(uid_a, uid_b, source='clients:manual_link')
            if ok:
                try:
                    # Clear opt-out so future suggestions can happen if needed
                    self.db.set_link_opt_out_by_uid(uid_a, 0, source='clients:manual_link')
                    self.db.set_link_opt_out_by_uid(uid_b, 0, source='clients:manual_link')
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0540', 'suppressed exception excpass_0540', __spina_exc)
                    pass
                messagebox.showinfo('Linked', f"Linked '{name}' and '{target}'.")
                win.destroy()
                self.refresh_clients()
            else:
                err = ''
                try:
                    err = self.db.get_last_error()
                except Exception:
                    err = ''
                if err and 'already linked' in err.lower():
                    messagebox.showinfo('Already Linked', err)
                else:
                    messagebox.showerror('Failed', err or 'Linking failed.')

        def cancel():
            win.destroy()

        ttk.Button(btns, text='Link', command=do_link).pack(side='right', padx=6)
        ttk.Button(btns, text='Cancel', command=cancel).pack(side='right')

        try:
            win.bind('<Return>', lambda e: do_link())
            win.bind('<Escape>', lambda e: cancel())
        except Exception as e:
            _log_ignored("ui.bind failed", e, key="ui.bind_failed")

    def unlink_selected_client(self):
        """Unlink the selected client (clears person_uid for the whole link group)."""
        sel = self.clients_tree.selection()
        if not sel:
            messagebox.showwarning('Select', 'Please select a client first.')
            return
        iid = sel[0]
        name = self.clients_tree.item(iid, 'values')[0]
        lt = self._mode_filter()
        try:
            tags = self.clients_tree.item(iid, 'tags') or ()
            for t in tags:
                if str(t).startswith('lt:'):
                    lt = str(t).split(':', 1)[1]
                    break
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0541', 'suppressed exception excpass_0541', __spina_exc)
            pass
        info = self.db.get_client_info(name, loan_type=lt) or {}
        pu = (info.get('person_uid') or '').strip()
        if not pu:
            messagebox.showinfo('Not linked', 'This client is not linked.')
            return
        if not messagebox.askyesno('Unlink', 'Unlink this person group? (Regular + 7x7 will be separate again)'):
            return
        if self.db.unlink_person_uid(pu, source='clients:manual_unlink'):
            messagebox.showinfo('Unlinked', 'Unlinked successfully.')
            self.refresh_clients()
        else:
            messagebox.showerror('Failed', 'Unlink failed.')

    def import_missing(self):
        n = self.db.import_missing_clients_from_transactions()
        messagebox.showinfo('Imported', f'Imported {n} clients')
        self.refresh_clients(); self.refresh_reports(); self.refresh_data_grid()

    def import_from_excel(self):
        if not HAVE_XL:
            messagebox.showwarning("Missing", "Install openpyxl to use Excel import.")
            return
        path = filedialog.askopenfilename(title="Select Excel file", filetypes=[("Excel files","*.xlsx;*.xlsm;*.xltx;*.xltm")])
        if not path:
            return
        try:
            wb = load_workbook(path, read_only=True, data_only=True)
            ws = wb.active
            headers = [cell.value for cell in ws[1] if cell.value]
            if not headers or len(headers) < 2:
                messagebox.showerror("Error", "Invalid template format  must have 'Client Name' + date columns.")
                return
            # convert header dates
            date_cols = []
            for h in headers[1:]:
                if isinstance(h, (datetime, date)):
                    date_cols.append(h.strftime("%Y-%m-%d"))
                elif isinstance(h, str):
                    parsed = None
                    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d-%m-%Y"):
                        try:
                            parsed = datetime.strptime(h.strip(), fmt)
                            date_cols.append(parsed.strftime("%Y-%m-%d"))
                            break
                        except Exception as __spina_exc:
                            _log_suppressed_once('excpass_0542', 'suppressed exception excpass_0542', __spina_exc)
                            pass
            if not date_cols:
                messagebox.showerror("Error", "No valid date headers found in Excel file.")
                return
            db_names = {r["name"].strip().lower() for r in self.db.conn.execute("SELECT name FROM clients")}
            missing = []
            imported = 0
            for row_idx, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
                if not row or not row[0]:
                    continue
                name = str(row[0]).strip()
                if name.strip().lower() not in db_names:
                    missing.append((row_idx, name))
                    continue
                for i, dcol in enumerate(date_cols):
                    try:
                        val = row[i + 1] if len(row) > i + 1 else None
                        if val is None or val == "":
                            continue
                        amt = float(val)
                        if amt != 0:
                            self.db.add_or_update_transaction(name, dcol, amt, description="Imported Payment")
                            imported += 1
                    except Exception:
                        continue
            wb.close()
            self.refresh_all()
            if missing:
                msg = " These names dont match existing clients and were skipped:\n\n"
                msg += "\n".join([f"Row {r}: {n}" for r, n in missing])
                messagebox.showwarning("Name Mismatch", msg)
            messagebox.showinfo("Import Complete", f"Imported {imported} payment entries successfully.")
        except Exception as e:
            messagebox.showerror("Error", f"Import failed: {e}")

    def export_monthly_template(self):
        """Export an Excel template for the current visible month (view-only data entry).
        Columns: Client Name + one column per date (YYYY-MM-DD).
        Users will fill payments in Excel and use 'Import from Excel' to load into the app.
        """
        try:
            from tkinter import filedialog, messagebox
            try:
                from openpyxl import Workbook
            except Exception:
                messagebox.showwarning("Missing", "Install openpyxl to export the Excel template.")
                return

            import calendar as _calendar
            year, month = self.grid_year, self.grid_month
            days = _calendar.monthrange(year, month)[1]

            # Build workbook
            wb = Workbook()
            ws = wb.active
            ws.title = f"{year}-{month:02d}"

            # Header row
            headers = ["Client Name"] + [f"{year}-{month:02d}-{d:02d}" for d in range(1, days+1)]
            for c, h in enumerate(headers, start=1):
                ws.cell(row=1, column=c, value=h)

            # Client names (from DB, current search filter)
            search_term = getattr(self, "search_db_var", None)
            term = search_term.get().strip() if search_term else ""
            clients = self.db.get_all_clients(search=term if term else None, loan_type=self._mode_filter(), search_by='all')
            row = 2
            for name in clients:
                nm = name['name'] if isinstance(name, dict) else name
                ws.cell(row=row, column=1, value=nm)
                row += 1

            # Ask path and save
            default_name = f"Daily_Template_{year}-{month:02d}.xlsx"
            path = filedialog.asksaveasfilename(
                title="Save Excel Template",
                initialfile=default_name,
                defaultextension=".xlsx",
                filetypes=[("Excel Workbook", "*.xlsx")]
            )
            if not path:
                return
            messagebox.showinfo("Template Saved", f"Excel template saved to:\n{path}\n\nFill in amounts and use 'Import from Excel' to load data.")
        except Exception as e:
            try:
                messagebox.showerror("Export Error", str(e))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0543', 'suppressed exception excpass_0543', __spina_exc)
                pass

    def import_clients_from_excel(self):
        """Import ONLY client details from an Excel file into the Clients DB.

        Multi-loan-type safe:
        - If the sheet has a "Loan Type" column, it imports per-row (Regular / 7x7).
        - Otherwise, it imports into the CURRENT view mode (top selector).
        """
        from tkinter import filedialog, messagebox
        try:
            from openpyxl import load_workbook
        except Exception:
            messagebox.showwarning("Missing", "Install openpyxl to use Excel import.")
            return

        path = filedialog.askopenfilename(
            title="Select Excel file for Clients",
            filetypes=[("Excel files", "*.xlsx;*.xlsm;*.xltx;*.xltm")]
        )
        if not path:
            return

        def _norm_lt(val):
            try:
                s = (val or "").strip()
            except Exception:
                s = ""
            if not s:
                return self._mode_filter()
            s2 = s.lower().replace(" ", "")
            return "7x7" if ("7x7" in s2 or "7×7" in s2 or "7x" in s2) else "Regular"

        import datetime as _dt

        def to_date(val):
            if val in (None, ""):
                return ""
            try:
                if hasattr(val, "strftime"):
                    return val.strftime("%Y-%m-%d")
                s = str(val).strip()
                for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y"):
                    try:
                        return _dt.datetime.strptime(s, fmt).strftime("%Y-%m-%d")
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0544', 'suppressed exception excpass_0544', __spina_exc)
                        pass
                return s
            except Exception:
                return ""

        def to_float(val, default=0.0):
            try:
                if val in (None, ""):
                    return default
                return float(str(val).replace(",", ".").strip())
            except Exception:
                return default

        try:
            wb = load_workbook(path, read_only=True, data_only=True)
            ws = wb.active

            headers = [str(c.value).strip() if c.value is not None else "" for c in ws[1]]
            if not headers:
                messagebox.showerror("Error", "The first row must contain headers.")
                return

            low = [h.lower() for h in headers]

            def find_col(*names):
                for n in names:
                    n2 = n.lower()
                    if n2 in low:
                        return low.index(n2)
                return None

            c_name = find_col("client name", "name", "client")
            c_contact = find_col("contact number", "contact no", "contact", "phone", "mobile", "cell", "cp number", "tel", "telephone")
            c_area = find_col("area")
            c_prin = find_col("principal", "amount", "loan", "loan amount")
            c_rel = find_col("date released", "released", "release date", "date_released")
            c_due = find_col("due date", "due", "maturity", "due_date")
            c_rate = find_col("interest rate", "rate", "interest_rate")
            c_lt = find_col("loan type", "loan_type", "type")
            c_new_until = find_col("new until", "new_until", "new expiry", "new_expiry")
            c_term = find_col("payment term", "term", "terms", "pay term", "payment frequency", "frequency", "payment_term")
            c_pay = find_col("payment amount", "payment", "pay amount", "payment_amount", "installment", "amortization", "amount per term", "per term", "daily payment", "weekly payment", "monthly payment")
            c_mode = find_col("payment mode", "mode of payment", "payment_mode", "mop")
            c_flex_due = find_col("flexible due rule", "flex due rule", "due rule", "due schedule", "salary rule", "flex_due_rule")

            if c_name is None:
                messagebox.showerror("Error", "Missing required header: 'Client Name' or 'Name'.")
                return

            # Existing (name, loan_type) map for updates
            existing = {}
            try:
                for r in self.db.conn.execute("SELECT name, loan_type FROM clients"):
                    try:
                        nm = (r[0] or "").strip()
                        lt = _norm_lt(r[1] if len(r) > 1 else None)
                        if nm:
                            existing[(nm.lower(), lt)] = nm
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0545', 'suppressed exception excpass_0545', __spina_exc)
                        pass
            except Exception:
                for r in self.db.conn.execute("SELECT name, loan_type FROM clients"):
                    nm = (r[0] or "").strip()
                    if nm:
                        try:
                            _lt = (r[1] or '').strip()
                        except Exception:
                            _lt = ''
                        _lt = '7x7' if str(_lt).lower().replace(' ', '') in ('7x7','7×7') else 'Regular'
                        existing[(nm.lower(), _lt)] = nm

            created, updated_count, skipped = 0, 0, []

            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row:
                    continue
                raw_name = row[c_name] if c_name < len(row) else None
                if raw_name is None or str(raw_name).strip() == "":
                    continue

                name = str(raw_name).strip()

                # Determine loan type for this row
                lt_row = self._mode_filter()
                if c_lt is not None and c_lt < len(row):
                    lt_row = _norm_lt(row[c_lt])
                else:
                    lt_row = _norm_lt(None)

                area = ""
                if c_area is not None and c_area < len(row) and row[c_area] is not None:
                    area = str(row[c_area]).strip()

                contact = ""
                if c_contact is not None and c_contact < len(row) and row[c_contact] is not None:
                    try:
                        contact = str(row[c_contact]).strip()
                    except Exception:
                        contact = ""

                # Payment term / amount
                def _norm_term(v):
                    try:
                        s = str(v or '').strip()
                    except Exception:
                        s = ''
                    if not s:
                        return 'Daily'
                    s2 = s.lower().replace('-', '').replace('_', '').replace(' ', '')
                    if s2.startswith('d'):
                        return 'Daily'
                    if 'week' in s2 or s2.startswith('w'):
                        return 'Weekly'
                    if 'semi' in s2 or 'bi' in s2 or 'quin' in s2:
                        return 'Semi'
                    if 'month' in s2 or s2.startswith('m'):
                        return 'Monthly'
                    t = s.strip().title()
                    return t if t in ('Daily','Weekly','Semi','Monthly') else 'Daily'

                pay_term = 'Daily'
                if c_term is not None and c_term < len(row):
                    pay_term = _norm_term(row[c_term])

                pay_amt = 0.0
                if c_pay is not None and c_pay < len(row):
                    pay_amt = to_float(row[c_pay], default=0.0)

                pay_mode = "Cash"
                if c_mode is not None and c_mode < len(row) and row[c_mode] is not None:
                    try:
                        pay_mode = _spina__merge_payment_mode(row[c_mode])
                    except Exception:
                        pay_mode = "Cash"

                flex_due_rule = ""
                if c_flex_due is not None and c_flex_due < len(row) and row[c_flex_due] is not None:
                    try:
                        flex_due_rule = str(row[c_flex_due]).strip()
                    except Exception:
                        flex_due_rule = ""

                principal = None
                if c_prin is not None and c_prin < len(row):
                    principal = to_float(row[c_prin], default=0.0)

                dr = ""
                if c_rel is not None and c_rel < len(row):
                    dr = to_date(row[c_rel])

                dd = ""
                if c_due is not None and c_due < len(row):
                    dd = to_date(row[c_due])

                # Interest rate (optional)
                ir = None
                if c_rate is not None and c_rate < len(row):
                    ir = to_float(row[c_rate], default=0.0)
                    if ir > 1.0:
                        ir = ir / 100.0

                # 7x7 always has 0% interest
                if lt_row.lower().replace(" ", "") == "7x7":
                    ir = 0.0

                # New-until (optional)
                nu = None
                if c_new_until is not None and c_new_until < len(row):
                    nu = to_date(row[c_new_until]) or ""

                key = (name.lower(), lt_row)

                if key in existing:
                    try:
                        self.db.update_client(
                            existing[key],
                            new_name=name,
                            principal=principal,
                            date_released=dr if dr else None,
                            area=area,
                            interest_rate=ir,
                            new_until=nu,
                            loan_type=lt_row,
                            contact_number=contact,
                            payment_term=pay_term,
                            payment_amount=pay_amt,
                            payment_mode=pay_mode,
                            flex_due_rule=flex_due_rule
                        )
                        if dd:
                            try:
                                self.db.set_due_date(name, dd, loan_type=lt_row)
                            except TypeError:
                                self.db.set_due_date(name, dd)
                            except Exception as __spina_exc:
                                _log_suppressed_once('excpass_0546', 'suppressed exception excpass_0546', __spina_exc)
                                pass
                        updated_count += 1
                    except Exception as e:
                        skipped.append((f"{name} ({lt_row})", str(e)))
                else:
                    ok = False
                    try:
                        ok = self.db.add_client(
                            name,
                            principal if principal is not None else 0.0,
                            dr if dr else None,
                            area,
                            ir,
                            (nu if (nu is not None and str(nu).strip()) else None),
                            lt_row,
                            pay_start_offset_days=1,
                            contact_number=contact,
                            payment_term=pay_term,
                            payment_amount=pay_amt,
                            payment_mode=pay_mode,
                            flex_due_rule=flex_due_rule
                        )
                    except TypeError:
                        try:
                            ok = self.db.add_client(name, principal if principal is not None else 0.0, dr if dr else None)
                            if area:
                                try:
                                    self.db.update_client(name, area=area, loan_type=lt_row)
                                except Exception as __spina_exc:
                                    _log_suppressed_once('excpass_0547', 'suppressed exception excpass_0547', __spina_exc)
                                    pass
                        except Exception as e:
                            skipped.append((f"{name} ({lt_row})", str(e)))
                            ok = False
                    except Exception as e:
                        skipped.append((f"{name} ({lt_row})", str(e)))
                        ok = False

                    if ok:
                        created += 1
                        existing[key] = name

                    if dd:
                        try:
                            self.db.set_due_date(name, dd, loan_type=lt_row)
                        except Exception as __spina_exc:
                            _log_suppressed_once('excpass_0548', 'suppressed exception excpass_0548', __spina_exc)
                            pass

            wb.close()

            # Refresh UI
            try:
                self.refresh_clients()
                self.refresh_reports()
                self.refresh_data_grid()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0549', 'suppressed exception excpass_0549', __spina_exc)
                pass

            msg = f"Imported clients: {created} new, {updated_count} updated."
            if skipped:
                msg += f"\n\nSkipped {len(skipped)} row(s):\n" + "\n".join([f"- {n}: {err}" for n, err in skipped[:10]])
                if len(skipped) > 10:
                    msg += f"\n...and {len(skipped) - 10} more."
            messagebox.showinfo("Clients Import", msg)

        except Exception as e:
            try:
                messagebox.showerror("Error", f"Import failed: {e}")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0550', 'suppressed exception excpass_0550', __spina_exc)
                pass

# ---------------- Client dialog ----------------
    class ClientDialog(simpledialog.Dialog):
        def __init__(self, parent, title=None, initial=None, areas_provider=None, area_adder=None):
