            ttk.Label(master, text='Other Payment Mode:').grid(row=12, column=0, sticky='w')
            self.paymode_other_entry = ttk.Entry(master, textvariable=self.paymode_other_var, width=30)
            self.paymode_other_entry.grid(row=12, column=1, pady=5)

            def _toggle_paymode_other(*_):
                try:
                    is_other = ((self.paymode_var.get() or '').strip() == 'Others')
                except Exception:
                    is_other = False
                try:
                    self.paymode_other_entry.configure(state=('normal' if is_other else 'disabled'))
                except Exception:
                    pass
                if not is_other:
                    try:
                        self.paymode_other_var.set('')
                    except Exception:
                        pass

            _toggle_paymode_other()
            try:
                self.paymode_var.trace_add('write', lambda *a: _toggle_paymode_other())
            except Exception as e:
                _log_ignored("ui.trace_add failed", e, key="ui.trace_add_failed")

            # When editing an existing client, lock the loan type to avoid cross-type move bugs
            try:
                if isinstance(self.client, dict) and self.client.get('id'):
                    cb_lt.configure(state='disabled')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0556', 'suppressed exception excpass_0556', __spina_exc)
                pass

            def _sync_type():
                lt = (self.type_var.get() or '').strip()
                is_7x7 = (lt.lower().replace(' ', '') == '7x7')
                try:
                    if is_7x7:
                        self.rate_var.set('0')
                        self.rate_entry.configure(state='disabled')
                    else:
                        self.rate_entry.configure(state='normal')
                        if str(self.rate_var.get()).strip() in ('', '0', '0.0'):
                            self.rate_var.set(str(self.client.get('interest_rate', 0.20) or 0.20))
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0557', 'suppressed exception excpass_0557', __spina_exc)
                    pass
            _sync_type()
            try:
                self.type_var.trace_add('write', lambda *a: _sync_type())
            except Exception as e:
                _log_ignored("ui.trace_add failed", e, key="ui.trace_add_failed")

            return master

        def validate(self):
            try:
                from tkinter import messagebox
            except Exception:
                messagebox = None
            name = (self.name_var.get() or '').strip()
            if not name:
                if messagebox: messagebox.showerror('Required', 'Client Name is required.')
                return False
            # Area validation (must exist in Areas master list, unless blank)
            area = (self.area_var.get() or '').strip()
            if area:
                try:
                    areas = list(self.areas_provider()) if callable(getattr(self, 'areas_provider', None)) else list(getattr(self, '_areas_cache', []) or [])
                    areas_set = set([a.strip() for a in areas if str(a).strip()])
                except Exception:
                    areas_set = set()
                if areas_set and (area not in areas_set):
                    if messagebox: messagebox.showerror('Invalid', 'Area not in Areas list. Please add it first.')
                    return False
            if self.mark_new_var.get():
                s = (self.new_until_var.get() or '').strip()
                if not s:
                    if messagebox: messagebox.showerror('Required', 'Please enter a "New until" date (YYYY-MM-DD) or untick Mark as NEW.')
                    return False
                import datetime as _dt
                try:
                    _dt.datetime.strptime(s, '%Y-%m-%d')
                except Exception:
                    if messagebox: messagebox.showerror('Invalid date', 'Use format YYYY-MM-DD for "New until".')
                    return False
            # Date Released validation (YYYY-MM-DD). Payments start the next day.
            dr = (getattr(self, 'date_var', tk.StringVar(value='')).get() or '').strip()
            if dr:
                import datetime as _dt
                try:
                    _dt.datetime.strptime(dr, '%Y-%m-%d')
                except Exception:
                    if messagebox: messagebox.showerror('Invalid date', 'Use format YYYY-MM-DD for "Date Released".')
                    return False

            # Payment amount validation (optional)
            try:
                amt_txt = (getattr(self, 'payamt_var', tk.StringVar(value='')).get() or '').strip()
                if amt_txt:
                    float(str(amt_txt).replace(',', '.').strip())
            except Exception:
                if messagebox: messagebox.showerror('Invalid', 'Payment Amount must be a number.')
                return False

            return True
        def apply(self):
            principal_text = str(self.principal_var.get()).replace(',', '.').strip()
            rate_text = str(self.rate_var.get()).replace(',', '.').strip()
            try:
                principal = float(principal_text) if principal_text else 0.0
            except ValueError:
                messagebox.showerror('Invalid', 'Principal must be a number (e.g. 10.00 or 10,00)')
                return
            try:
                interest_rate = float(rate_text) if rate_text else 0.0
            except ValueError:
                messagebox.showerror('Invalid', 'Interest Rate must be a number (e.g. 0.2 or 20)')
                return

            # Force no-interest for 7x7
            try:
                lt = (getattr(self, 'type_var', tk.StringVar(value='Regular')).get() or '').strip()
                if lt.lower().replace(' ', '') == '7x7':
                    interest_rate = 0.0
                    self.rate_var.set('0')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0558', 'suppressed exception excpass_0558', __spina_exc)
                pass

            # Persist new_until only when Mark as NEW is checked
            nu = self.new_until_var.get().strip() if self.mark_new_var.get() else ''

            # Payment term/amount
            try:
                pt = (getattr(self, 'payterm_var', tk.StringVar(value='Daily')).get() or '').strip()
            except Exception:
                pt = 'Daily'
            if pt not in ('Daily','Weekly','Semi','Monthly'):
                pt2 = pt.lower().replace(' ', '').replace('-', '').replace('_', '')
                if 'week' in pt2:
                    pt = 'Weekly'
                elif 'semi' in pt2 or 'bi' in pt2:
                    pt = 'Semi'
                elif 'month' in pt2:
                    pt = 'Monthly'
                else:
                    pt = 'Daily'
            try:
                pa_txt = (getattr(self, 'payamt_var', tk.StringVar(value='')).get() or '').strip()
                pa = float(str(pa_txt).replace(',', '.').strip()) if pa_txt else 0.0
            except Exception:
                pa = 0.0

            self.result = {
                'name': self.name_var.get().strip(),
                'contact_number': (getattr(self, 'contact_var', tk.StringVar(value='')).get() or '').strip(),
                'payment_term': pt,
                'payment_amount': pa,
                'payment_mode': _spina__merge_payment_mode(
                    (getattr(self, 'paymode_var', tk.StringVar(value='Cash')).get() or '').strip() or 'Cash',
                    (getattr(self, 'paymode_other_var', tk.StringVar(value='')).get() or '').strip()
                ),
                'area': self.area_var.get().strip(),
                'principal': principal,
                'interest_rate': interest_rate,
                'loan_type': (getattr(self, 'type_var', tk.StringVar(value='Regular')).get().strip() or 'Regular'),
                'date_released': self.date_var.get().strip(),
                'pay_start_offset_days': (1 if bool(getattr(self, 'pay_next_day_var', tk.BooleanVar(value=False)).get()) else 0),
                'payment_start_date': (getattr(self, 'paystart_var', tk.StringVar(value='')).get() or '').strip(),
                'mark_new': bool(self.mark_new_var.get()),
                'new_until': nu,
            }

