    class RenewDialog(simpledialog.Dialog):
        def __init__(self, parent, title=None, initial=None, loan_type='Regular'):
            self.client = initial or {}
            self.loan_type = loan_type or 'Regular'
            super().__init__(parent, title or 'Renew Client')

        def body(self, master):
            frm = ttk.Frame(master)
            frm.pack(fill='both', expand=True, padx=10, pady=10)

            def _row(r, label, widget):
                ttk.Label(frm, text=label).grid(row=r, column=0, sticky='w', pady=4, padx=(0,8))
                widget.grid(row=r, column=1, sticky='ew', pady=4)
                return r+1

            frm.columnconfigure(1, weight=1)

            name = (self.client.get('name') or '')
            try:
                p0 = float(self.client.get('principal') or 0)
            except Exception:
                p0 = 0.0
            try:
                r0 = float(self.client.get('interest_rate') or 0.20)
            except Exception:
                r0 = 0.20

            self.date_var = tk.StringVar(value=date.today().strftime("%Y-%m-%d"))
            self.released_cash_var = tk.StringVar(value="")
            self.new_principal_var = tk.StringVar(value=f"{p0:g}")
            self.rate_var = tk.StringVar(value=str((r0*100.0) if r0 <= 1 else r0))
            self.note_var = tk.StringVar(value="")

            r = 0
            r = _row(r, "Client", ttk.Label(frm, text=name, font=('Segoe UI', 10, 'bold')))
            r = _row(r, "Renew Date (YYYY-MM-DD)", ttk.Entry(frm, textvariable=self.date_var, width=18))

            # Start of Payment for the NEW cycle (after renew)
            try:
                _renew_init_off = int((self.client.get('pay_start_offset_days') if isinstance(self.client, dict) else 0) or 0)
            except Exception:
                _renew_init_off = 0
            self.pay_next_day_var = tk.BooleanVar(value=True if _renew_init_off >= 1 else False)
            r = _row(r, "Start of Payment", ttk.Checkbutton(frm, text="Next day (optional; uncheck = same day)", variable=self.pay_next_day_var))

            r = _row(r, "Released Cash (PHP)", ttk.Entry(frm, textvariable=self.released_cash_var, width=18))
            r = _row(r, "New Principal", ttk.Entry(frm, textvariable=self.new_principal_var, width=18))

            rate_entry = ttk.Entry(frm, textvariable=self.rate_var, width=18)
            r = _row(r, "Interest Rate (%)", rate_entry)

            if (self.loan_type or '').strip().lower() != 'regular':
                try:
                    rate_entry.state(['disabled'])
                except Exception:
                    rate_entry.configure(state='disabled')

            ttk.Label(frm, text="Note (optional)").grid(row=r, column=0, sticky='nw', pady=4, padx=(0,8))
            self.note_txt = tk.Text(frm, height=3, width=30)
            self.note_txt.grid(row=r, column=1, sticky='ew', pady=4)
            r += 1

            hint = ("Tip: If you leave New Principal blank, it will use Released Cash as the new principal."
                    if (self.loan_type or '').strip().lower() == 'regular'
                    else "7x7 renewals use daily interest (ceil(balance/1000) × 7). Interest Rate is disabled.")
            ttk.Label(frm, text=hint).grid(row=r, column=0, columnspan=2, sticky='w', pady=(8,0))

            return frm

        def validate(self):
            try:
                float((self.released_cash_var.get() or '').strip())
            except Exception:
                messagebox.showerror('Invalid', 'Please enter Released Cash (number).')
                return False

            d = (self.date_var.get() or '').strip()
            try:
                datetime.strptime(d[:10], "%Y-%m-%d")
            except Exception:
                messagebox.showerror('Invalid', 'Please use YYYY-MM-DD for Renew Date.')
                return False

            ptxt = (self.new_principal_var.get() or '').strip()
            if ptxt:
                try:
                    float(ptxt)
                except Exception:
                    messagebox.showerror('Invalid', 'New Principal must be a number (or leave it blank).')
                    return False

            if (self.loan_type or '').strip().lower() == 'regular':
                rtxt = (self.rate_var.get() or '').strip()
                try:
                    float(rtxt)
                except Exception:
                    messagebox.showerror('Invalid', 'Interest Rate must be a number (percent).')
                    return False

            return True

        def apply(self):
            note = ''
            try:
                note = self.note_txt.get('1.0', 'end').strip()
            except Exception:
                note = ''

            ir = None
            if (self.loan_type or '').strip().lower() == 'regular':
                try:
                    ir = float((self.rate_var.get() or '').strip())
                    if ir > 1.0:
                        ir = ir / 100.0
                except Exception:
                    ir = None

            self.result = {
                'renew_date': (self.date_var.get() or '').strip()[:10],
                'released_cash': (self.released_cash_var.get() or '').strip(),
                'new_principal': (self.new_principal_var.get() or '').strip(),
                'interest_rate': ir,
                'note': note,
                'pay_start_offset_days': (1 if bool(getattr(self, 'pay_next_day_var', tk.BooleanVar(value=True)).get()) else 0),
            }

