    def export_clients_template(self):
        """Export a blank Excel template for importing client details.
        Columns: Client Name | Area | Principal | Date Released | Due Date
        """
        from tkinter import filedialog, messagebox
        try:
            from openpyxl import Workbook
        except Exception:
            messagebox.showwarning("Missing", "Install openpyxl to export the Excel template.")
            return

        wb = Workbook()
        ws = wb.active
        ws.title = "Clients"

        headers = ["Client Name", "Contact Number", "Loan Type", "Area", "Principal", "Date Released", "Due Date", "Payment Term", "Payment Amount", "Payment Mode", "Flexible Due Rule"]
        for c, h in enumerate(headers, start=1):
