    def export_range_template(self):
        """Export an Excel template for payments over a chosen date range.
        Presets: This Month / This Year / Custom (YYYY-MM-DD)."""
        import calendar as _cal
        import datetime as _dt
        import tkinter as tk
        from tkinter import ttk, messagebox, filedialog

        try:
            from openpyxl import Workbook
        except Exception:
            messagebox.showwarning("Missing", "Install openpyxl to export the Excel template.")
            return

        # --- Preset dialog ---
        dlg = tk.Toplevel(self.root)
        dlg.title("Choose Export Range")
        dlg.transient(self.root)
        dlg.grab_set()
        dlg.resizable(False, False)

        sel = tk.StringVar(value="month")
        tk.Label(dlg, text="Export range:", font=("TkDefaultFont", 10, "bold")).grid(row=0, column=0, columnspan=2, padx=12, pady=(12,4), sticky="w")
        ttk.Radiobutton(dlg, text="This Month", value="month", variable=sel).grid(row=1, column=0, sticky="w", padx=12)
        ttk.Radiobutton(dlg, text="This Year",  value="year",  variable=sel).grid(row=2, column=0, sticky="w", padx=12)
        ttk.Radiobutton(dlg, text="Custom",     value="custom",variable=sel).grid(row=3, column=0, sticky="w", padx=12, pady=(0,6))

        # Custom fields
        tk.Label(dlg, text="Start (YYYY-MM-DD):").grid(row=4, column=0, sticky="w", padx=12)
        sv_start = tk.StringVar()
        sv_end   = tk.StringVar()
        e_start = ttk.Entry(dlg, width=18, textvariable=sv_start); e_start.grid(row=4, column=1, sticky="w", padx=6)
        tk.Label(dlg, text="End (YYYY-MM-DD):").grid(row=5, column=0, sticky="w", padx=12)
        e_end = ttk.Entry(dlg, width=18, textvariable=sv_end);     e_end.grid(row=5, column=1, sticky="w", padx=6)

        def on_sel(*_):
            state = ("normal" if sel.get() == "custom" else "disabled")
            e_start.config(state=state); e_end.config(state=state)
        sel.trace_add("write", on_sel); on_sel()

        # Buttons
        btns = ttk.Frame(dlg); btns.grid(row=6, column=0, columnspan=2, pady=10)
        ok_pressed = {"value": False}
        def _ok(): ok_pressed["value"] = True; dlg.destroy()
        def _cancel(): dlg.destroy()
        ttk.Button(btns, text="Export", command=_ok).pack(side="left", padx=6)
        ttk.Button(btns, text="Cancel", command=_cancel).pack(side="left", padx=6)

        # Center dialog
        dlg.update_idletasks()
        try:
            x = self.root.winfo_rootx() + (self.root.winfo_width()//2 - dlg.winfo_width()//2)
            y = self.root.winfo_rooty() + (self.root.winfo_height()//2 - dlg.winfo_height()//2)
            dlg.geometry(f"+{max(0,x)}+{max(0,y)}")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0559', 'suppressed exception excpass_0559', __spina_exc)
            pass

        self.root.wait_window(dlg)
        if not ok_pressed["value"]:
            return

        today = _dt.date.today()
        if sel.get() == "month":
            y, m = today.year, today.month
            d0 = _dt.date(y, m, 1)
            d1 = _dt.date(y, m, _cal.monthrange(y, m)[1])
        elif sel.get() == "year":
            y = today.year
            d0 = _dt.date(y, 1, 1)
            d1 = _dt.date(y, 12, 31)
        else:
            # READ FROM STRINGVARS
            s0, s1 = sv_start.get().strip(), sv_end.get().strip()
            try:
                d0 = _dt.datetime.strptime(s0, "%Y-%m-%d").date()
                d1 = _dt.datetime.strptime(s1, "%Y-%m-%d").date()
            except Exception:
                messagebox.showerror("Invalid Date", "Please enter valid dates in YYYY-MM-DD format.")
                return
            if d1 < d0:
                d0, d1 = d1, d0

        # Build date list (inclusive) and warn on very large range
        days = (d1 - d0).days + 1
        if days > 93 and not messagebox.askyesno("Large Range", f"You selected {days} days. Continue?"):
            return

        # Build workbook
        wb = Workbook()
        ws = wb.active
        ws.title = f"{d0.isoformat()} to {d1.isoformat()}"[:31]

        headers = ["Client Name"] + [(d0 + _dt.timedelta(days=i)).isoformat() for i in range(days)]
        for c, h in enumerate(headers, start=1):
            ws.cell(row=1, column=c, value=h)

        # Client names (respect current search filter)
        search_term = getattr(self, "search_db_var", None)
        term = search_term.get().strip() if search_term else ""
        clients = self.db.get_all_clients(search=term if term else None, loan_type=self._mode_filter(), search_by='all')
        row = 2
        for name in clients:
            nm = name['name'] if isinstance(name, dict) else name
            ws.cell(row=row, column=1, value=nm)
            row += 1

        # Save
        default_name = f"Export_{d0.isoformat()}_to_{d1.isoformat()}.xlsx"
        path = filedialog.asksaveasfilename(
            title="Save Excel Template",
            initialfile=default_name,
            defaultextension=".xlsx",
            filetypes=[("Excel Workbook", "*.xlsx")]
        )
        if not path:
            return
        try:
            wb.save(path)
        except Exception as e:
            messagebox.showerror("Save Error", str(e))
            return

        messagebox.showinfo("Template Saved", f"Excel template saved to:\n{path}\n\nFill in amounts and use 'Import from Excel' to load data.")

    def attach_direct_integration(app):
        """
        Minimal integration after removing undo/redo/backups.
        - Ensures a DB is attached
        - Wraps Excel import with a safe error dialog (if present)
        - Triggers initial UI refreshes (if methods exist)
        """
        import tkinter.messagebox as messagebox

        # 1) Ensure a DB is attached
        try:
            dbfile = globals().get('DB_FILE', 'loans.db')
        except Exception:
            dbfile = 'loans.db'

        try:
            if not getattr(app, 'db', None):
                # LoanDB should be in the same module; adjust import if not
                from __main__ import LoanDB as _LoanDB
                app.db = _LoanDB(dbfile)
        except Exception:
            # If DB creation fails, the app may still show UI but with no data
            pass

        # 2) Make Excel import safer (optional, only if method exists)
        try:
            if hasattr(app, 'import_from_excel') and not getattr(app, '_import_wrapped', False):
                _orig = app.import_from_excel

                def _wrapped_import(*args, **kwargs):
                    try:
                        return _orig(*args, **kwargs)
                    except Exception as ex:
                        try:
                            messagebox.showerror("Import Failed", str(ex))
                        except Exception as __spina_exc:
                            _log_suppressed_once('excpass_0560', 'suppressed exception excpass_0560', __spina_exc)
                            pass
                        return None

                app.import_from_excel = _wrapped_import
                app._import_wrapped = True
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0561', 'suppressed exception excpass_0561', __spina_exc)
            pass

        # 3) Initial refreshes (only if methods exist)
        for fn in ('refresh_clients', 'refresh_data_grid', 'refresh_reports'):
            try:
                if hasattr(app, fn):
                    getattr(app, fn)()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0562', 'suppressed exception excpass_0562', __spina_exc)
                pass

            # ---------- Helpers FIRST ----------
            def _capture_databank_click(e):
                """Remember the exact (client, day) cell clicked in the days_tree."""
                try:
                    tv = getattr(app, "days_tree", None)
