    class DBSnapshots:
        def __init__(self, db_path):
            self.db_path = db_path
            self._tmpdir = os.path.join(os.getcwd(), '.db_snapshots')
            os.makedirs(self._tmpdir, exist_ok=True)
            # ensure we have an initial snapshot
            self.push_initial()

        def _snap_name(self):
            ts = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
            return os.path.join(self._tmpdir, f'snap_{ts}_{uuid.uuid4().hex}.db')

        def push_initial(self):
            if os.path.exists(self.db_path):
                p = self._snap_name()
                try:
                    shutil.copy2(self.db_path, p)
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0578', 'suppressed exception excpass_0578', __spina_exc)
                    pass

        def push(self):
            try:
                if os.path.exists(self.db_path):
                    p = self._snap_name()
                    shutil.copy2(self.db_path, p)
                    print('[UNDO] Snapshot created:', p)
                    return True
            except Exception as e:
                traceback.print_exc()
            return False

        def _swap_file(self, src):
            """Overwrite DB file with snapshot src. Close and reopen connections handled externally."""
            if not os.path.exists(src):
                raise FileNotFoundError(src)
            shutil.copy2(src, self.db_path)
            return True

        def cleanup(self):
            # keep last few snapshots; remove old ones beyond limit
            try:
                keep = 200
                snaps = sorted(
                    [os.path.join(self._tmpdir, f) for f in os.listdir(self._tmpdir)],
                    key=os.path.getmtime
                )
                remove = snaps[:-keep] if len(snaps) > keep else []
                for r in remove:
                    try:
                        os.remove(r)
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0579', 'suppressed exception excpass_0579', __spina_exc)
                        pass
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0580', 'suppressed exception excpass_0580', __spina_exc)
                pass

